use vstd::prelude::*;

verus! {
    /// Append two `Vec<f32>`s by moving their contents into a fresh `Vec<f32>`.
    ///
    /// Postconditions:
    ///   1. The resulting vector has length `arr.len() + values.len()`.
    ///   2. For all `i < arr.len()`, `result[i] == arr[i]`.
    ///   3. For all `j < values.len()`, `result[arr.len() + j] == values[j]`.
    fn numpy_append(arr: Vec<f32>, values: Vec<f32>) -> (result: Vec<f32>)
        ensures
            result.len() == arr.len() + values.len(),
            forall |i: usize| i < arr.len() ==>
                result[i] == arr[i],
            forall |j: usize| j < values.len() ==>
                result[arr.len() + j] == values[j],
    {
        // Pre‐allocate enough space for both input vectors
        let total_len = arr.len() + values.len();
        let mut result = Vec::with_capacity(total_len);

        // Move all elements out of `arr` into `result`
        result.extend(arr);
        // Move all elements out of `values` into `result`
        result.extend(values);

        result
    }
}

